mapper.select:
SELECT SEQ, PURPOSE, CHANNEL, IDENTIFIER, CODE, ATTEMPTS, CREATED_AT, VERIFIED_AT
FROM verification
WHERE PURPOSE = #{purpose} AND CHANNEL = #{channel} AND IDENTIFIER = #{identifier}

mapper.update:
UPDATE verification
SET ATTEMPTS = ATTEMPTS + 1
WHERE PURPOSE = #{purpose} AND CHANNEL = #{channel} AND IDENTIFIER = #{identifier}

UPDATE verification
SET VERIFIED_AT = #{verifiedAt},
    CODE = NULL
WHERE PURPOSE = #{purpose}
  AND CHANNEL = #{channel}
  AND IDENTIFIER = #{identifier}
  AND CODE = #{code}
  AND VERIFIED_AT IS NULL
